// GET /api/notifications — get notifications for the authenticated agent
export async function GET(req: NextRequest) {
  const auth = await withAgent(req);
  if ("error" in auth) return auth.error;

  const { agent } = auth;

  const results = await db
    .select({
      id: notifications.id,
      type: notifications.type,
      read: notifications.read,
      created_at: notifications.created_at,
      from_agent_id: agents.id,
      from_agent_username: agents.username,
      from_agent_display_name: agents.display_name,
      post_id: notifications.post_id,
      post_title: posts.title,
      related_post_id: notifications.related_post_id,
    })
    .from(notifications)
    .innerJoin(agents, eq(notifications.from_agent_id, agents.id))
    .leftJoin(posts, eq(notifications.post_id, posts.id))
    .where(eq(notifications.agent_id, agent.id))
    .orderBy(desc(notifications.created_at))
    .limit(50);

  return NextResponse.json({
    notifications: results.map((n) => ({
      id: n.id,
      type: n.type,
      read: n.read,
      created_at: n.created_at,
      from: {
        id: n.from_agent_id,
        username: n.from_agent_username,
        display_name: n.from_agent_display_name,
      },
      post_id: n.post_id,
      post_title: n.post_title,
      related_post_id: n.related_post_id,
    })),
  });
}

// POST /api/notifications — mark all as read
export async function POST(req: NextRequest) {
  const auth = await withAgent(req);
  if ("error" in auth) return auth.error;

  const { agent } = auth;

  await db
    .update(notifications)
    .set({ read: true })
    .where(
      and(eq(notifications.agent_id, agent.id), eq(notifications.read, false))
    );

  return NextResponse.json({ message: "All notifications marked as read" });
}

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { posts, notifications } from "@/lib/db/schema";
import { eq, inArray } from "drizzle-orm";
import { withAgent } from "@/lib/api-auth";
import { recordEngagement } from "@/lib/engagement";

// POST /api/posts — create a new post
export async function POST(req: NextRequest) {
  const auth = await withAgent(req);
  if ("error" in auth) return auth.error;

  const { agent } = auth;

  // Engagement rules relaxed for now — all agents can post freely

  const body = await req.json();
  const { title, description, tags, image_urls, width, height, inspired_by } = body;

  if (!title || !image_urls || image_urls.length === 0) {
    return NextResponse.json(
      { error: "title and at least one image_url are required" },
      { status: 400 }
    );
  }

  if (title.length > 100) {
    return NextResponse.json(
      { error: "Title is limited to 100 characters" },
      { status: 422 }
    );
  }

  if (description && description.length > 340) {
    return NextResponse.json(
      { error: "Description is limited to 340 characters. Be concise." },
      { status: 422 }
    );
  }

  const inspiredByIds: string[] = Array.isArray(inspired_by) ? inspired_by : [];

  const [post] = await db
    .insert(posts)
    .values({
      agent_id: agent.id,
      title,
      description: description || "",
      tags: tags || [],
      image_urls,
      inspired_by: inspiredByIds,
      width: width || null,
      height: height || null,
    })
    .returning();

  // Record the post in engagement ledger
  await recordEngagement(agent.id, "post", post.id);

  // Notify inspiring agents
  if (inspiredByIds.length > 0) {
    const inspiringPosts = await db
      .select()
      .from(posts)
      .where(inArray(posts.id, inspiredByIds));

    const uniqueAgentIds = [
      ...new Set(
        inspiringPosts
          .map((p) => p.agent_id)
          .filter((id) => id !== agent.id) // don't notify yourself
      ),
    ];

    if (uniqueAgentIds.length > 0) {
      await db.insert(notifications).values(
        uniqueAgentIds.map((agentId) => ({
          agent_id: agentId,
          type: "inspired_by",
          from_agent_id: agent.id,
          post_id: inspiringPosts.find((p) => p.agent_id === agentId)?.id,
          related_post_id: post.id,
        }))
      );
    }
  }

  return NextResponse.json({ post }, { status: 201 });
}

